BEGIN;
DO $t$
DECLARE emp uuid:=gen_random_uuid(); u uuid:=gen_random_uuid(); sid uuid:=gen_random_uuid(); a uuid:=gen_random_uuid(); b uuid:=gen_random_uuid(); c uuid:=gen_random_uuid(); tr1 uuid:=gen_random_uuid(); tr2 uuid:=gen_random_uuid(); perfil uuid:=gen_random_uuid(); var uuid:=gen_random_uuid(); desp uuid; rec uuid; op uuid:=gen_random_uuid(); v jsonb; itens jsonb; estoque uuid:=gen_random_uuid(); forn uuid; sol uuid; pai uuid; desd uuid; grupo uuid; cot uuid; ped uuid; r1 uuid; r2 uuid; nota1 uuid; nota2 uuid; item uuid; conc uuid;
BEGIN
 INSERT INTO auth.users(id,email,aud,role) VALUES(u,'homologacao-'||u::text||'@example.invalid','authenticated','authenticated');
 INSERT INTO public.empresas(id,nome) VALUES(emp,'Empresa fictícia teste lotes');
 INSERT INTO public.ew_niveis_acesso(empresa_id,nivel,nome) VALUES(emp,1,'Teste ADM') ON CONFLICT DO NOTHING;
 INSERT INTO public.ew_niveis_permissoes(empresa_id,nivel,chave,permitido) SELECT emp,1,chave,true FROM public.ew_permissoes_catalogo ON CONFLICT(empresa_id,nivel,chave) DO UPDATE SET permitido=true;
 INSERT INTO public.usuarios_empresas(empresa_id,usuario_id,perfil,nivel_acesso) VALUES(emp,u,'administrador',1);
 INSERT INTO public.usuarios_login(usuario_id,empresa_id,perfil,ativo,nome,login,nivel_acesso) VALUES(u,emp,'administrador',true,'Usuário fictício','teste-'||u::text,1);
 INSERT INTO public.ew_sessoes_unicas(usuario_id,sessao_auth_id) VALUES(u,sid);
 PERFORM set_config('request.jwt.claims',jsonb_build_object('sub',u,'session_id',sid,'role','authenticated')::text,true);
 INSERT INTO public.obras(id,empresa_id,nome,codigo) VALUES(a,emp,'Obra fictícia A','TESTE-A'),(b,emp,'Obra fictícia B','TESTE-B'),(c,emp,'Obra fictícia C','TESTE-C');
 INSERT INTO public.ew_estoques_locais(empresa_id,obra_id,criado_por) VALUES(emp,a,u),(emp,b,u),(emp,c,u) ON CONFLICT DO NOTHING;
 INSERT INTO public.ew_locais_fisicos(empresa_id,nome,ativo) VALUES(emp,'G1',true),(emp,'G2',true),(emp,'G3',true) ON CONFLICT DO NOTHING;
 INSERT INTO public.ew_perfis(id,empresa_id,codigo,descricao,fabricante,comprimento_comercial_mm) VALUES(perfil,emp,'TESTE-01','Perfil fictício','Fabricante teste',6000);
 INSERT INTO public.ew_materiais_variacoes(id,empresa_id,tipo,perfil_id,ativo) VALUES(var,emp,'perfil',perfil,true);
 INSERT INTO public.ew_cem_obras_materiais(empresa_id,obra_id,tipo,perfil_id,variacao_id,quantidade_prevista,unidade_prevista) VALUES(emp,a,'perfil',perfil,var,3,'BARRA');
 INSERT INTO public.ew_fornecedores(empresa_id,nome,ativo) VALUES(emp,'Fornecedor fictício',true);
 INSERT INTO public.ew_obra_orcamento(empresa_id,obra_id,valor_total,aluminio,acessorios,vidros,outros,fabricacao,instalacao,criado_por) VALUES(emp,a,1000,1000,0,0,0,0,0,u);
 SELECT id INTO STRICT forn FROM public.ew_fornecedores WHERE empresa_id=emp;
 INSERT INTO public.ew_compras_locais_empresa(id,empresa_id,nome,criado_por) VALUES(estoque,emp,'Estoque de teste',u);
 itens:=jsonb_build_array(jsonb_build_object('chave','TESTE','variacao_id',var,'comprimento_mm',6000,'unidade','BARRA','quantidade',3,'valor_total_centavos',10000));
 INSERT INTO public.ew_compras_solicitacoes(empresa_id,obra_id,operacao_id,itens,criado_por) VALUES(emp,a,gen_random_uuid(),itens,u) RETURNING id INTO pai;
 INSERT INTO public.ew_compras_solicitacoes(empresa_id,obra_id,operacao_id,itens,criado_por) VALUES(emp,a,gen_random_uuid(),itens,u) RETURNING id INTO sol;
 INSERT INTO ew_compras_interna.grupos_compra(empresa_id,codigo,nome,criado_por) VALUES(emp,'TESTE','Grupo teste',u) RETURNING id INTO grupo;
 INSERT INTO ew_compras_interna.fornecedores_grupos(empresa_id,grupo_id,fornecedor_id,criado_por) VALUES(emp,grupo,forn,u);
 INSERT INTO ew_compras_interna.materiais_grupos(empresa_id,grupo_id,variacao_id,criado_por) VALUES(emp,grupo,var,u);
 INSERT INTO ew_compras_interna.desdobramentos(empresa_id,solicitacao_id,operacao_id,criado_por) VALUES(emp,pai,gen_random_uuid(),u) RETURNING id INTO desd;
 INSERT INTO ew_compras_interna.desdobramentos_grupos(empresa_id,desdobramento_id,grupo_id,solicitacao_filha_id,nome_grupo,itens) VALUES(emp,desd,grupo,sol,'Grupo teste',itens);
 INSERT INTO public.ew_compras_cotacoes(empresa_id,solicitacao_id,fornecedor_id,operacao_id,itens,total_centavos,criado_por) VALUES(emp,sol,forn,gen_random_uuid(),itens,10000,u) RETURNING id INTO cot;
 INSERT INTO public.ew_compras_pedidos(empresa_id,solicitacao_id,cotacao_id,fornecedor_id,obra_id,operacao_id,itens,total_centavos,criado_por) VALUES(emp,sol,cot,forn,a,gen_random_uuid(),itens,10000,u) RETURNING id INTO ped;
 PERFORM set_config('role','authenticated',true);
 v:=public.ew_compras_receber_pedido(ped,'G1',jsonb_build_array(jsonb_build_object('chave','TESTE','quantidade',1)),op);r1:=(v->>'id')::uuid;
 v:=public.ew_compras_receber_pedido(ped,'G1',jsonb_build_array(jsonb_build_object('chave','TESTE','quantidade',2)),gen_random_uuid());r2:=(v->>'id')::uuid;
 PERFORM set_config('role','postgres',true);
 INSERT INTO public.ew_obra_despesas(empresa_id,obra_id,categoria,valor,origem,fornecedor,numero_documento,data_documento,status,criado_por,aprovado_por,aprovado_em,operacao_id)
 VALUES(emp,a,'aluminio',100,'manual','Fornecedor fictício','NF-PARCIAL',current_date,'aprovada',u,u,now(),gen_random_uuid()) RETURNING id INTO desp;
 INSERT INTO public.ew_obra_despesas_itens(despesa_id,empresa_id,codigo_fornecedor,descricao,unidade,quantidade,valor_unitario,valor_total,perfil_id)
 VALUES(desp,emp,'TESTE-01','Perfil fictício','BARRA',3,33.333333,100,perfil) RETURNING id INTO item;
 PERFORM set_config('role','authenticated',true);
 v:=public.ew_compras_vincular_nfe_pedido(ped,desp,jsonb_build_array(jsonb_build_object('despesa_item_id',item,'recebimento_id',r1,'chave','TESTE'),jsonb_build_object('despesa_item_id',item,'recebimento_id',r2,'chave','TESTE')),gen_random_uuid());conc:=(v->>'id')::uuid;
 SET CONSTRAINTS ALL IMMEDIATE;
 PERFORM set_config('role','postgres',true);
 IF (SELECT sum(custo_centavos) FROM ew_compras_interna.custo_lotes WHERE empresa_id=emp AND fonte='PEDIDO_OBRA') IS DISTINCT FROM 10000::numeric THEN RAISE EXCEPTION 'Nota única conciliada a dois recebimentos não abriu lotes'; END IF;
 IF (SELECT count(*) FROM ew_compras_interna.custo_lotes WHERE empresa_id=emp AND fonte='PEDIDO_OBRA')<>2 OR (SELECT sum(custo_centavos) FROM ew_compras_interna.custo_lotes WHERE empresa_id=emp AND quantidade=1) IS DISTINCT FROM 3333::numeric OR (SELECT sum(custo_centavos) FROM ew_compras_interna.custo_lotes WHERE empresa_id=emp AND quantidade=2) IS DISTINCT FROM 6667::numeric THEN RAISE EXCEPTION 'Rateio por recebimento incorreto'; END IF;
 PERFORM set_config('role','authenticated',true);
 v:=public.ew_compras_compromissos_obra(emp,a);
 IF NOT EXISTS(SELECT 1 FROM jsonb_array_elements(v) x WHERE x->>'categoria'='aluminio' AND (x->>'realizado_centavos')::numeric=10000 AND (x->>'comprometido_pendente_centavos')::numeric=0 AND (x->>'consumido_centavos')::numeric=10000) THEN RAISE EXCEPTION 'Pedido e nota contados duas vezes: %',v; END IF;
 v:=public.ew_transferir_estoque_entre_obras(emp,a,b,var,6000,'BARRA',3,'G1','G2','Transferência teste',tr1);
 BEGIN v:=public.ew_compras_desvincular_nfe(conc,'Desvinculação prematura',gen_random_uuid()); RAISE EXCEPTION 'TESTE_FALHOU'; EXCEPTION WHEN raise_exception THEN IF SQLERRM='TESTE_FALHOU' THEN RAISE; END IF; END;
 v:=public.ew_estornar_transferencia_entre_obras(emp,tr1,'Estorno teste',gen_random_uuid());
 v:=public.ew_compras_desvincular_nfe(conc,'Desvinculação teste',gen_random_uuid());
 PERFORM set_config('role','postgres',true);
 IF (SELECT count(*) FROM ew_compras_interna.custo_lotes WHERE empresa_id=emp AND cancelado_em IS NOT NULL)<>2 THEN RAISE EXCEPTION 'Rateio fiscal não foi estornado'; END IF;
 IF EXISTS(SELECT 1 FROM ew_compras_interna.custo_saldos_fragmentos WHERE empresa_id=emp) THEN RAISE EXCEPTION 'Lote fiscal cancelado ainda disponível'; END IF;
END;$t$;
ROLLBACK;
SELECT 'nota única com dois recebimentos aprovada' resultado;